fun main() {
    val b = readln().toInt()
    var counter = 0
    val sqrtVal = sqrt(b.toDouble())
    val sqrtInt = sqrtVal.toInt()

    for (i in 2 until sqrtInt) {
        if (b % i == 0) {
            counter += 2
        }
    }
    if (sqrtVal == sqrtInt.toDouble()) {
        counter++
    }
    println(if (b == 1) 1 else counter + 2)
}

fun main() {
    val b = readln().toInt()
    if (b == 1) {
        println(1)
        return
    }
    var counter = 0
    var i = 2
    while (i * i < b) {
        if (b % i == 0) counter += 2
        i++
    }
    if (i * i == b) counter++
    println(counter + 2)
}

